#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <iterator>
int main(){std::vector<int>a{4,1,3,2},b;int offset=10;std::transform(a.begin(),a.end(),std::back_inserter(b),[offset](int x){return x+offset;});std::sort(b.begin(),b.end(),[](int a,int b){return a>b;});auto p=std::find_if(b.begin(),b.end(),[](int x){return x%2==0;});std::cout<<std::accumulate(b.begin(),b.end(),0)<<' '<<*p<<' '<<std::distance(b.begin(),p)<<'\n';std::vector<int>empty;std::cout<<(std::find(empty.begin(),empty.end(),7)==empty.end())<<' '<<std::accumulate(empty.begin(),empty.end(),0)<<'\n';}
